package com.riskguard.transaction.api;
import com.riskguard.transaction.api.dto.DashboardDtos; import com.riskguard.transaction.service.DashboardService; import java.util.UUID; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/dashboard") public class DashboardController { private final DashboardService service; public DashboardController(DashboardService service){this.service=service;} @GetMapping public DashboardDtos.Summary summary(@AuthenticationPrincipal Jwt jwt){var roles=jwt.getClaimAsStringList("roles");boolean elevated=roles!=null&&(roles.contains("ROLE_ANALYST")||roles.contains("ROLE_ADMIN"));return service.summary(UUID.fromString(jwt.getSubject()),elevated);} }
